// Shared provably-fair vectors of SPEC-0007@2 (tests/vectors/fairness-v1.json, the same file the C# Fairness tests
// read). Generated by tests/vectors/generate_fairness_v1.py; never edited by hand.
import type { RoundVerificationData } from "@apogeu/game-sdk/fairness";

import rawVectors from "../../../vectors/fairness-v1.json";

export interface FairnessVector extends RoundVerificationData {
  readonly description?: string;
}

export const fairnessVectors: readonly FairnessVector[] = rawVectors as FairnessVector[];

/** The same hex string with its first digit changed (still lowercase hex of the same length). */
export function tamperHex(hex: string): string {
  const first = hex.charAt(0);
  return `${first === "0" ? "1" : "0"}${hex.slice(1)}`;
}

/** A different crash point with 2 places: one hundredth above the claimed value. */
export function tamperCrashPoint(crashPoint: string): string {
  const hundredths = BigInt(crashPoint.replace(".", "")) + 1n;
  const text = hundredths.toString().padStart(3, "0");
  return `${text.slice(0, -2)}.${text.slice(-2)}`;
}
